// Moore FSM, onehot->int state translation, explicit next-state
// function, reset-to-initial-state longhand (explicit register
// chain, independent of the FSM).
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg out
);
    // Onehot-to-int state translation
    reg [1:0] state_int;
    always @(*) begin
        case (1) // state_int
            (1'b1) state_int = 2'b00;
            (1'b1) state_int = 2'b01;
            (1'b1) state_int = 2'b10;
            (1'b1) state_int = 2'b11;
            default: state_int = 2'b00;
        endcase
    end
    // Explicit next-state function
    reg [1:0] state_next_int;
    always @(*) begin
        case (state_int)
            2'b00: state_next_int = in ? 2'b01 : 2'b00;
            2'b01: state_next_int = in ? 2'b10 : 2'b01;
            2'b10: state_next_int = in ? 2'b00 : 2'b10;
            2'b11: state_next_int = in ? 2'b11 : 2'b01;
            default: state_next_int = 2'b00;
        endcase
    end
    // Register chain, active-high reset to go to state A (the
    // equivalent of the longhand register chain in the combinational
    // next-state function).
    reg [1:0] state_reg0, state_reg1, state_reg2;
    always @(posedge clk) begin
        if (reset) begin
            state_reg0 <= 2'b00;
            state_reg1 <= 2'b00;
            state_reg2 <= 2'b00;
        end else begin
            state_reg0 <= state_next_int[0];
            state_reg1 <= state_next_int[1];
            state_reg2 <= state_reg0;
        end
    end
    // Output function
    always @(*) begin
        out = (state_reg2 == 2'b11);
    end
endmodule

