// Moore state machine, one input, one output, four states. Synchronous reset
// to state A on active high, synchronous next state (registered).
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output out
);
    reg [1:0] state, next_state;
    reg out_reg;
    always @(*) begin
        case (state)
            2'd0: begin next_state = 2'd0; out_reg = 1'd0; end
            2'd1: begin next_state = in ? 2'd1 : 2'd2; out_reg = 1'd0; end
            2'd2: begin next_state = in ? 2'd0 : 2'd3; out_reg = 1'd0; end
            2'd3: begin next_state = in ? 2'd2 : 2'd1; out_reg = 1'd1; end
        endcase
    end
    always @(posedge clk) begin
        if (reset) state <= 2'd0;
        else state <= next_state;
    end
    assign out = out_reg;
endmodule

